// ===== #10 稳定性基础工具：防抖、节流、可清理资源登记 =====

// 防抖：连续触发只在停止 wait 毫秒后执行最后一次，避免重复提交/刷新。
function debounce(fn, wait) {
  let timer = null;
  const debounced = function (...args) {
    if (timer) clearTimeout(timer);
    timer = setTimeout(() => {
      timer = null;
      fn.apply(this, args);
    }, wait);
  };
  debounced.cancel = () => {
    if (timer) clearTimeout(timer);
    timer = null;
  };
  return debounced;
}

// 节流：固定间隔内最多执行一次，用于滚动等高频事件。
function throttle(fn, interval) {
  let last = 0;
  let timer = null;
  return function (...args) {
    const now = Date.now();
    const remaining = interval - (now - last);
    if (remaining <= 0) {
      if (timer) { clearTimeout(timer); timer = null; }
      last = now;
      fn.apply(this, args);
    } else if (!timer) {
      timer = setTimeout(() => {
        last = Date.now();
        timer = null;
        fn.apply(this, args);
      }, remaining);
    }
  };
}

// 视图级资源登记表：切换视图前统一清理定时器、监听器、未完成请求，防止内存泄漏。
const viewCleanup = {
  _tasks: [],
  // 登记一个清理回调，返回它本身便于即时调用
  add(fn) {
    if (typeof fn === "function") this._tasks.push(fn);
    return fn;
  },
  // 登记一个定时器，切换视图时自动 clearInterval
  addInterval(id) {
    this._tasks.push(() => clearInterval(id));
    return id;
  },
  // 登记一个 AbortController，切换视图时自动 abort 未完成请求
  addAbort(controller) {
    this._tasks.push(() => { try { controller.abort(); } catch (e) {} });
    return controller;
  },
  // 执行并清空所有登记的清理任务
  runAll() {
    const tasks = this._tasks.slice();
    this._tasks = [];
    tasks.forEach((fn) => { try { fn(); } catch (e) {} });
  }
};

// ===== L841-L846 renderExternalLink =====
function renderExternalLink(url, label) {
  const normalized = normalizeExternalUrl(url);
  if (!normalized) return "";
  return `<a class="ghost link-like external-link" href="${normalized}" target="_blank" rel="noopener noreferrer">${label}</a>`;
}


// ===== L1760-L1765 getDashboardTypeTone =====
function getDashboardTypeTone(type) {
  if (type === "素人贴") return "people";
  if (type === "话题贴") return "topic";
  return "lead";
}


// ===== L2028-L2035 getMonthDates =====
function getMonthDates(monthString) {
  if (!monthString) return [];
  const [year, month] = String(monthString).split("-").map(Number);
  if (!year || !month) return [];
  const lastDay = new Date(year, month, 0).getDate();
  return Array.from({ length: lastDay }, (_, index) => `${monthString}-${String(index + 1).padStart(2, "0")}`);
}


